INSERT INTO feature VALUES('rust-record','runtime','The record of a Rust function','foreign-calls','partial','uncommon','mainstream languages','A reader on rustc''s own libraries, under the pinned toolchain, takes the build''s command line for a crate word for word and gives each requested function''s v0 symbol, the passage of each operand as rustc computes it for the build (its mode, its LLVM type and its extension), and the layout of each type of its signature, under the toolchain''s commit and the target. Each symbol of the record is a symbol of the built object, the record agrees with the `define` line that rustc emits for six functions, and each layout equals what `std.layout` computes for its eleven types. A function that the build copies into each caller has no symbol, and the record states that. One canonical byte form with a bounded reader keeps each record in a cache under its request and the digest of each source that the reader read, so a second request starts no process. The reader refuses a generic, a private and a missing function, and a type whose layout the record does not state, each by name. No call uses the record yet.','runtime-rust-record runtime-rust-reader',NULL,NULL,'#327');
